327	ENTRYPOINT Bool
328	unk_handle_event (ModeInfo *mi, XEvent *event)
329	{
330	  unk_configuration *bp = &bps[MI_SCREEN(mi)];
331	
332	  if (event->xany.type == ButtonPress &&
333	      (event->xbutton.button == Button4 ||
334	       event->xbutton.button == Button5 ||
335	       event->xbutton.button == Button6 ||
336	       event->xbutton.button == Button7))
337	    {
338	      int b = event->xbutton.button;
339	      int speed = 1;
340	      if (b == Button6 || b == Button7)
341	        speed *= 3;
342	      if (bp->orthop)
343	        switch (b) {				/* swap axes */
344	        case Button4: b = Button6; break;
345	        case Button5: b = Button7; break;
346	        case Button6: b = Button4; break;
347	        case Button7: b = Button5; break;
348	        }
349	      gltrackball_mousewheel (bp->trackball, b, speed, !!event->xbutton.state);
350	      return True;
351	    }
352	
353	# ifdef DEBUG
354	  else if (event->type == KeyPress)
355	    {
356	      KeySym keysym;
357	      char c = 0;
358	      GLfloat i = 0.1;
359	      XLookupString (&event->xkey, &c, 1, &keysym, 0);
360	      switch (keysym) {
361	      case XK_Up:    poly1 += i; break;
362	      case XK_Down:  poly1 -= i; break;
363	      case XK_Left:  poly2 += i; break;
364	      case XK_Right: poly2 -= i; break;
365	      default: break;
366	      }
367	      fprintf (stderr,"%.2f %.2f\n", poly1, poly2);
368	      return True;
369	    }
370	# endif /* DEBUG */
371	
372	  else if (gltrackball_event_handler (event, bp->trackball,
373	                                      MI_WIDTH (mi), MI_HEIGHT (mi),
374	                                      &bp->button_down_p))
375	    return True;
376	  else if (screenhack_event_helper (MI_DISPLAY(mi), MI_WINDOW(mi), event))
377	    {
378	      bp->orthop = !bp->orthop;
379	      reshape_unk (mi, MI_WIDTH(mi), MI_HEIGHT(mi));
380	      return True;
381	    }
382	
383	  return False;
384	}
