508	ENTRYPOINT void 
509	init_unk (ModeInfo *mi)
510	{
511	  unk_configuration *bp;
512	  int wire = MI_IS_WIREFRAME(mi);
513	  int i;
514	
515	  MI_INIT (mi, bps);
516	
517	  bp = &bps[MI_SCREEN(mi)];
518	
519	  bp->glx_context = init_GL(mi);
520	
521	  bp->orthop = ortho_arg;
522	  bp->resolution = resolution_arg;
523	  bp->amplitude = amplitude_arg;
524	  bp->noise = noise_arg;
525	  bp->aspect = aspect_arg;
526	  bp->speed = speed_arg;
527	  bp->frames = buzz_arg ? 15 : 1;
528	  if (bp->resolution < 1) bp->resolution = 1;
529	  if (bp->resolution > 300) bp->resolution = 300;
530	  if (bp->amplitude < 0.01) bp->amplitude = 0.01;
531	  if (bp->amplitude > 1) bp->amplitude = 1;
532	  if (bp->noise < 0.01) bp->noise = 0.01;
533	  if (bp->speed <= 0.001) bp->speed = 0.001;
534	
535	  parse_color (mi, "foreground", "Foreground", bp->fg);
536	  parse_color (mi, "background", "Background", bp->bg);
537	
538	  reshape_unk (mi, MI_WIDTH(mi), MI_HEIGHT(mi));
539	
540	  bp->trackball = gltrackball_init (False);
541	
542	  if (MI_COUNT(mi) < 1) MI_COUNT(mi) = 1;
543	  /* bp->count is set in reshape */
544	
545	  load_image (mi);
546	
547	  bp->base = glGenLists (1);
548	  glNewList (bp->base, GL_COMPILE);
549	  {
550	    GLfloat h1 = 0.01;
551	    GLfloat h2 = 0.02;
552	    GLfloat h3 = (h1 + h2) / 2;
553	    GLfloat s = 0.505;
554	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
555	    glVertex3f (-s, -s, -h1);
556	    glVertex3f ( s, -s, -h1);
557	    glVertex3f ( s,  s, -h1);
558	    glVertex3f (-s,  s, -h1);
559	    glEnd();
560	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
561	    glVertex3f (-s, -s, 0);
562	    glVertex3f (-s, -s, -h2);
563	    glVertex3f ( s, -s, -h2);
564	    glVertex3f ( s, -s, 0);
565	    glEnd();
566	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
567	    glVertex3f (-s, -s, 0);
568	    glVertex3f (-s, -s, -h2);
569	    glVertex3f (-s,  s, -h2);
570	    glVertex3f (-s,  s, 0);
571	    glEnd();
572	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
573	    glVertex3f ( s, -s, 0);
574	    glVertex3f ( s, -s, -h2);
575	    glVertex3f ( s,  s, -h2);
576	    glVertex3f ( s,  s, 0);
577	    glEnd();
578	    glBegin (wire ? GL_LINE_LOOP : GL_QUADS);
579	    glVertex3f (-s,  s, 0);
580	    glVertex3f (-s,  s, -h2);
581	    glVertex3f ( s,  s, -h2);
582	    glVertex3f ( s,  s, 0);
583	    glEnd();
584	
585	    glColor3fv (bp->fg);
586	    glBegin (GL_LINE_LOOP);
587	    s -= 0.01;
588	    glVertex3f (-s, -s, -h3);
589	    glVertex3f ( s, -s, -h3);
590	    glVertex3f ( s,  s, -h3);
591	    glVertex3f (-s,  s, -h3);
592	    glEnd();
593	  }
594	  glEndList ();
595	
596	  if (! wire)
597	    {
598	      glEnable (GL_LINE_SMOOTH);
599	      glHint (GL_LINE_SMOOTH_HINT, GL_NICEST);
600	      glBlendFunc (GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA); 
601	      glEnable (GL_BLEND);
602	    }
603	
604	  glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
605	
606	  for (i = 0; i < bp->count; i++)
607	    tick_unk (mi);
608	}
