718	ENTRYPOINT void
719	free_unk (ModeInfo *mi)
720	{
721	  unk_configuration *bp = &bps[MI_SCREEN(mi)];
722	  int i;
723	  if (!bp->glx_context) return;
724	  glXMakeCurrent(MI_DISPLAY(mi), MI_WINDOW(mi), *bp->glx_context);
725	  if (bp->trackball) gltrackball_free (bp->trackball);
726	  for (i = 0; i < bp->count * bp->frames * 2; i++)
727	    glDeleteLists (bp->lines[i], 1);
728	  free (bp->lines);
729	  free (bp->heights);
730	  if (bp->mask) XDestroyImage (bp->mask);
731	}
